<template><div><div class="page-head"><div><h1>Invoices</h1><p>Create, track and collect customer invoices.</p></div><button class="btn btn-primary" @click="openCreate">+ New invoice</button></div><div class="card mb-4 p-4"><div class="flex flex-col gap-3 md:flex-row"><input v-model="search" @keyup.enter="load" class="input md:max-w-sm" placeholder="Search invoice number…"><select v-model="status" @change="load" class="input md:max-w-44"><option value="">All statuses</option><option value="issued">Issued</option><option value="partial">Partial</option><option value="paid">Paid</option><option value="cancelled">Cancelled</option></select></div></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Client</th><th>Issue</th><th>Due</th><th>Total</th><th>Balance</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td><RouterLink :to="`/invoices/${i.id}`" class="font-bold text-indigo-600">{{i.invoice_number}}</RouterLink></td><td>{{i.client?.name}}</td><td>{{i.issue_date}}</td><td>{{i.due_date||'—'}}</td><td>{{money(i.total)}}</td><td>{{money(i.balance)}}</td><td><StatusBadge :value="i.status"/></td><td><div class="flex justify-end gap-2"><button v-if="i.status!=='cancelled' && !Number(i.amount_paid)" class="btn btn-soft" @click="cancel(i)">Cancel</button><button v-if="i.status!=='cancelled' && !Number(i.amount_paid)" class="btn btn-danger" @click="remove(i)">Delete</button></div></td></tr><tr v-if="!invoices.length"><td colspan="8"><div class="empty">No invoices found.</div></td></tr></tbody></table></div><AppModal :open="open" title="New invoice" subtitle="Issue a customer invoice with clear payment terms." @close="open=false"><form @submit.prevent="save"><div class="grid gap-4 md:grid-cols-3"><div class="md:col-span-2"><label class="label">Client *</label><select v-model="form.client_id" class="input" required><option :value="null">Select client</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Due date</label><input v-model="form.due_date" class="input" type="date"></div></div><div class="mt-5 rounded-2xl border border-slate-100 bg-slate-50/60 p-4"><div class="mb-3 flex items-center justify-between"><div class="text-xs font-bold">Invoice items</div><button type="button" class="btn btn-soft" @click="addItem">+ Add item</button></div><div v-for="(item,i) in form.items" :key="i" class="mb-2 grid grid-cols-[1fr_90px_120px_32px] gap-2"><select v-model="item.product_id" class="input" @change="priceFromProduct(item)" required><option :value="null">Select item</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model.number="item.quantity" class="input" type="number" min="0.001" step="0.001"><MoneyInput v-model="item.unit_price" :min="0" /><button type="button" class="icon-btn" @click="form.items.splice(i,1)" :disabled="form.items.length===1">×</button></div></div><div class="mt-5 flex justify-between"><div><label class="label">Discount</label><MoneyInput v-model="form.discount" class="max-w-40" :min="0" /></div><div class="text-right"><div class="text-[10px] uppercase tracking-wider text-slate-400">Total</div><div class="text-[10px] text-slate-400">Tax {{money(taxTotal)}}</div><div class="text-2xl font-extrabold">{{money(total)}}</div></div></div><div class="mt-5 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">{{saving?'Creating…':'Create invoice'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {computed,onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';import StatusBadge from '../../components/StatusBadge.vue';const {ask:confirm}=useConfirm();const toast=useToast();const invoices=ref<any[]>([]),clients=ref<any[]>([]),products=ref<any[]>([]),search=ref(''),status=ref(''),open=ref(false),saving=ref(false),error=ref('');const blankItem=()=>({product_id:null,description:'',quantity:1,unit_price:0,discount:0,tax_rate:0});const form=ref<any>({client_id:null,due_date:'',discount:0,notes:'',items:[blankItem()]});const total=computed(()=>Math.max(0,form.value.items.reduce((s:any,i:any)=>{const line=Math.max(0,Number(i.quantity||0)*Number(i.unit_price||0)-Number(i.discount||0));return s+line+(line*Number(i.tax_rate||0)/100)},0)-Number(form.value.discount||0)));
const taxTotal=computed(()=>form.value.items.reduce((s:any,i:any)=>{const line=Math.max(0,Number(i.quantity||0)*Number(i.unit_price||0)-Number(i.discount||0));return s+line*Number(i.tax_rate||0)/100},0));function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){invoices.value=(await api.get('/invoices',{params:{search:search.value,status:status.value,per_page:30}})).data.data}async function openCreate(){const [c,p]=await Promise.all([api.get('/clients',{params:{per_page:100}}),api.get('/products',{params:{per_page:100,active:true}})]);clients.value=c.data.data;products.value=p.data.data;form.value={client_id:null,due_date:'',discount:0,notes:'',items:[blankItem()]};open.value=true}function addItem(){form.value.items.push(blankItem())}function priceFromProduct(i:any){const p=products.value.find(x=>x.id===i.product_id);if(p){i.unit_price=Number(p.selling_price);i.tax_rate=Number(p.tax_rate)}}async function save(){saving.value=true;error.value='';try{await api.post('/invoices',form.value);open.value=false;await load();toast.success('Invoice created','Invoice was issued successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function cancel(i:any){if(!(await confirm({title:'Cancel invoice?',message:`${i.invoice_number} will be cancelled and removed from active receivables. This action cannot be undone.`,confirmText:'Cancel invoice',danger:true})))return;try{await api.put(`/invoices/${i.id}`,{status:'cancelled'});await load();toast.success('Invoice cancelled', `${i.invoice_number} was cancelled successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}async function remove(i:any){if(!(await confirm({title:'Delete invoice?',message:`${i.invoice_number} will be permanently deleted. This action cannot be undone.`,confirmText:'Delete invoice',danger:true})))return;try{await api.delete(`/invoices/${i.id}`);await load();toast.success('Invoice deleted', `${i.invoice_number} was deleted successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(load)</script>
